INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-noni-1', 'sent-ex-noni-1', 'en', 'I took the medicine and yet I am not getting better.', 'authored'),
  ('st-ex-noni-2', 'sent-ex-noni-2', 'en', 'I bought it even though it was expensive.', 'authored'),
  ('st-ex-noni-3', 'sent-ex-noni-3', 'en', 'I went out even though it was raining.', 'authored'),
  ('st-ex-noni-4', 'sent-ex-noni-4', 'en', 'I studied and yet I could not do the exam.', 'authored'),
  ('st-ex-keredo-1', 'sent-ex-keredo-1', 'en', 'It is cheap, but I am not buying it.', 'authored'),
  ('st-ex-keredo-2', 'sent-ex-keredo-2', 'en', 'I want to go, but I have no time.', 'authored'),
  ('st-ex-keredo-3', 'sent-ex-keredo-3', 'en', 'I rang, but nobody answered.', 'authored'),
  ('st-ex-keredo-4', 'sent-ex-keredo-4', 'en', 'It is difficult, but it is interesting.', 'authored'),
  ('st-ex-temo-1', 'sent-ex-temo-1', 'en', 'I will go even if it rains.', 'authored'),
  ('st-ex-temo-2', 'sent-ex-temo-2', 'en', 'I will buy it even if it is expensive.', 'authored'),
  ('st-ex-temo-3', 'sent-ex-temo-3', 'en', 'Even if I ask the teacher I do not understand.', 'authored'),
  ('st-ex-temo-4', 'sent-ex-temo-4', 'en', 'Even taking the medicine I do not get better.', 'authored'),
  ('st-ex-shi-1', 'sent-ex-shi-1', 'en', 'That shop is cheap, and it is close by.', 'authored'),
  ('st-ex-shi-2', 'sent-ex-shi-2', 'en', 'It is raining, and it is cold.', 'authored'),
  ('st-ex-shi-3', 'sent-ex-shi-3', 'en', 'I have no money, and I have no time either.', 'authored'),
  ('st-ex-shi-4', 'sent-ex-shi-4', 'en', 'The teacher is kind, and interesting too.', 'authored'),
  ('st-ex-aidani-1', 'sent-ex-aidani-1', 'en', 'I cleaned while my mother was asleep.', 'authored'),
  ('st-ex-aidani-2', 'sent-ex-aidani-2', 'en', 'I am going to Japan during the summer holidays.', 'authored'),
  ('st-ex-aidani-3', 'sent-ex-aidani-3', 'en', 'I tidy the room while my older brother is out.', 'authored'),
  ('st-ex-aidani-4', 'sent-ex-aidani-4', 'en', 'I read a book while I am on the train.', 'authored'),
  ('st-ex-maeato-1', 'sent-ex-maeato-1', 'en', 'I brush my teeth before going to bed.', 'authored'),
  ('st-ex-maeato-2', 'sent-ex-maeato-2', 'en', 'I take my medicine after eating.', 'authored'),
  ('st-ex-maeato-3', 'sent-ex-maeato-3', 'en', 'I shut the window before going out.', 'authored'),
  ('st-ex-maeato-4', 'sent-ex-maeato-4', 'en', 'I will ring after the meeting.', 'authored'),
  ('st-ex-made-1', 'sent-ex-made-1', 'en', 'I will wait until the teacher comes.', 'authored'),
  ('st-ex-made-2', 'sent-ex-made-2', 'en', 'I will do my homework by tomorrow.', 'authored'),
  ('st-ex-made-3', 'sent-ex-made-3', 'en', 'I worked until night.', 'authored'),
  ('st-ex-made-4', 'sent-ex-made-4', 'en', 'Please give it back by next week.', 'authored'),
  ('st-ex-nakutemon4-1', 'sent-ex-nakutemon4-1', 'en', 'You do not have to work today.', 'authored'),
  ('st-ex-nakutemon4-2', 'sent-ex-nakutemon4-2', 'en', 'You do not have to bring an umbrella.', 'authored'),
  ('st-ex-nakutemon4-3', 'sent-ex-nakutemon4-3', 'en', 'You do not have to get up early.', 'authored'),
  ('st-ex-nakutemon4-4', 'sent-ex-nakutemon4-4', 'en', 'You do not have to read all of it.', 'authored'),
  ('st-ex-nakucha-1', 'sent-ex-nakucha-1', 'en', 'I have got to go home now.', 'authored'),
  ('st-ex-nakucha-2', 'sent-ex-nakucha-2', 'en', 'I have to do my homework today.', 'authored'),
  ('st-ex-nakucha-3', 'sent-ex-nakucha-3', 'en', 'I have got to go to bed early.', 'authored'),
  ('st-ex-nakucha-4', 'sent-ex-nakucha-4', 'en', 'I have to take my medicine.', 'authored'),
  ('st-ex-bakari-1', 'sent-ex-bakari-1', 'en', 'My little brother does nothing but play games.', 'authored'),
  ('st-ex-bakari-2', 'sent-ex-bakari-2', 'en', 'I have only just got up.', 'authored'),
  ('st-ex-bakari-3', 'sent-ex-bakari-3', 'en', 'I have only just arrived in Japan.', 'authored'),
  ('st-ex-bakari-4', 'sent-ex-bakari-4', 'en', 'I eat nothing but meat.', 'authored')
